-- More workout plans: goal and equipment categories, demo fixes for 6 moves, 12 new plans, new Discover order.
ALTER TABLE public.plans DROP CONSTRAINT plans_goal_check;
ALTER TABLE public.plans ADD CONSTRAINT plans_goal_check CHECK (goal IN ('muscle','fat_loss','glutes','beginner','home','run','strength','mobility'));
ALTER TABLE public.plans ADD COLUMN equipment_key text;
UPDATE public.plans SET equipment_key = v.k FROM (VALUES ('build-muscle','dumbbells'),('lose-fat','dumbbells'),('glute-builder','dumbbells'),('walk-strength','none'),('home-no-equipment','none'),('first-5k','shoes')) AS v(slug, k) WHERE plans.slug = v.slug;
UPDATE public.plans SET goal = 'beginner' WHERE slug = 'home-no-equipment';

CREATE TEMP TABLE _move (k text PRIMARY KEY, ex text NOT NULL, name text NOT NULL, plain text NOT NULL, easier jsonb, harder jsonb) ON COMMIT DROP;

-- Swap the 6 moves that had no demo for library moves, same position in the workout
UPDATE public.plan_days d SET moves = jsonb_set(d.moves, '{3}', (SELECT jsonb_build_object('name', name, 'dose', '2x20', 'plain', plain, 'exercise_id', ex) FROM _move WHERE k = 'banded-glute-bridge')) FROM public.plans p WHERE p.id = d.plan_id AND p.slug = 'glute-builder' AND d.day_number = 3 AND d.week_number IS NULL AND d.moves->3->>'name' = 'Frog pump';
UPDATE public.plan_days d SET moves = jsonb_set(jsonb_set(d.moves, '{0}', (SELECT jsonb_build_object('name', name, 'dose', '3x12', 'plain', plain, 'exercise_id', ex) FROM _move WHERE k = 'bodyweight-squat')), '{2}', (SELECT jsonb_build_object('name', name, 'dose', '3x10 each side', 'plain', plain, 'exercise_id', ex) FROM _move WHERE k = 'single-leg-glute-bridge')) FROM public.plans p WHERE p.id = d.plan_id AND p.slug = 'home-no-equipment' AND d.day_number = 4 AND d.week_number IS NULL AND d.moves->0->>'name' = 'Squat to reach' AND d.moves->2->>'name' = 'Glute bridge march';
UPDATE public.plan_days d SET moves = jsonb_set(d.moves, '{1}', '{"name":"High plank","dose":"30 sec on / 30 sec off","plain":"Hold the top of a push-up with your hands under your shoulders and your body straight from head to heels.","exercise_id":"high-plank"}'::jsonb) FROM public.plans p WHERE p.id = d.plan_id AND p.slug = 'home-no-equipment' AND d.day_number = 3 AND d.week_number IS NULL AND d.moves->1->>'name' = 'Plank shoulder tap';
UPDATE public.plan_days d SET moves = jsonb_build_array(d.moves->0, (SELECT jsonb_build_object('name', name, 'dose', '1 min each side', 'plain', plain, 'exercise_id', ex) FROM _move WHERE k = 'kneeling-hip-flexor-stretch'), (SELECT jsonb_build_object('name', name, 'dose', '1 min each side', 'plain', plain, 'exercise_id', ex) FROM _move WHERE k = 'wall-hamstring-stretch'), (SELECT jsonb_build_object('name', name, 'dose', '2 min', 'plain', plain, 'exercise_id', ex) FROM _move WHERE k = 'doorway-chest-stretch'), (SELECT jsonb_build_object('name', name, 'dose', '2 min', 'plain', plain, 'exercise_id', ex) FROM _move WHERE k = 'childs-pose')) FROM public.plans p WHERE p.id = d.plan_id AND p.slug = 'home-no-equipment' AND d.day_number = 5 AND d.week_number IS NULL AND jsonb_array_length(d.moves) = 2 AND d.moves->1->>'name' = 'Guided stretch';
UPDATE public.plan_days d SET moves = jsonb_set(d.moves, '{2}', (SELECT jsonb_build_object('name', name, 'dose', '40 sec on / 20 sec off', 'plain', plain, 'exercise_id', ex) FROM _move WHERE k = 'side-lunge')) FROM public.plans p WHERE p.id = d.plan_id AND p.slug = 'lose-fat' AND d.day_number = 5 AND d.week_number IS NULL AND d.moves->2->>'name' = 'Skater step';

-- Twelve new plans

CREATE TEMP TABLE _day (slug text, day int, week int, title text, minutes text, note text, moves text) ON COMMIT DROP;
-- moves: key~dose[~name override], separated by |
SELECT p.id, d.day, d.week, d.title, d.minutes, d.note,
  (SELECT jsonb_agg(jsonb_build_object('name', coalesce(nullif(split_part(x.v, '~', 3), ''), m.name), 'dose', split_part(x.v, '~', 2), 'plain', m.plain,
      'exercise_id', m.ex, 'easier', m.easier, 'harder', m.harder) ORDER BY x.o)
   FROM unnest(string_to_array(d.moves, '|')) WITH ORDINALITY AS x(v, o)
   JOIN _move m ON m.k = split_part(x.v, '~', 1))
FROM _day d JOIN public.plans p ON p.slug = d.slug;

-- Body map for every new or changed day: main muscles 2, also worked 1
UPDATE public.plan_days d SET muscles = coalesce((
  SELECT jsonb_object_agg(x.r, x.lvl) FROM (
    SELECT r, max(lvl) AS lvl FROM jsonb_array_elements(d.moves) mv
    JOIN public.exercises e ON e.id = mv->>'exercise_id'
    CROSS JOIN LATERAL (SELECT unnest(e.primary_muscles) AS r, 2 AS lvl UNION ALL SELECT unnest(e.secondary_muscles), 1) u
    GROUP BY r) x), '{}'::jsonb)
FROM public.plans p
WHERE p.id = d.plan_id AND (p.slug IN ('gym-first-steps','twenty-minute-burn','kettlebell-burn','muscle-3-days','gym-upper-lower','glutes-at-home','gym-glutes','strength-foundations','bodyweight-strength','five-to-ten-k','daily-mobility','core-strong')
  OR (p.slug, d.day_number) IN (('glute-builder',3),('home-no-equipment',3),('home-no-equipment',4),('home-no-equipment',5),('lose-fat',5)));

-- Discover order
UPDATE public.plans SET sort_order = v.n FROM (VALUES ('walk-strength',1),('home-no-equipment',2),('gym-first-steps',3),('lose-fat',4),('twenty-minute-burn',5),('kettlebell-burn',6),('build-muscle',7),('muscle-3-days',8),('gym-upper-lower',9),('glute-builder',10),('glutes-at-home',11),('gym-glutes',12),('strength-foundations',13),('bodyweight-strength',14),('first-5k',15),('five-to-ten-k',16),('daily-mobility',17),('core-strong',18)) AS v(slug, n) WHERE plans.slug = v.slug;

ALTER TABLE public.plans ALTER COLUMN equipment_key SET NOT NULL;
ALTER TABLE public.plans ADD CONSTRAINT plans_equipment_key_check CHECK (equipment_key IN ('none','dumbbells','band','kettlebell','gym','shoes'));
