INSERT INTO _move VALUES
('archer-push-ups','archer-push-ups','Archer push-up','With your hands wide, lower toward one hand while the other arm stays straight, then push back up and switch sides.','{"name":"Wide push-up","note":"Both arms bend","exercise_id":"wide-grip-push-ups"}','{"name":"Lower for 3 seconds","note":"Keep the straight arm light"}'),
('banded-clamshell','banded-clamshell','Banded clamshell','Lie on your side with knees bent and a band above them, open your top knee like a clamshell, then close it slowly.','{"name":"No band","note":"Same move"}','{"name":"Pause at the top","note":"Hold open for 3 seconds each rep"}'),
('banded-fire-hydrant','banded-fire-hydrant','Banded fire hydrant','On your hands and knees with a band above your knees, lift one knee out to the side, then lower it slowly.','{"name":"No band","note":"Smaller lift"}','{"name":"Pause at the top","note":"Hold for 2 seconds each rep"}'),
('banded-glute-bridge','banded-glute-bridge','Banded glute bridge','With a mini band just above your knees, press your knees out and lift your hips into a bridge.','{"name":"Glute bridge","note":"No band","exercise_id":"glute-bridge"}','{"name":"Banded hip thrust","note":"Upper back on a couch or bench","exercise_id":"banded-hip-thrust"}'),
('banded-lateral-walk','banded-lateral-walk','Banded side walk','With a mini band above your knees and your knees slightly bent, take small steps sideways.','{"name":"Lighter band","note":"Or take smaller steps"}','{"name":"Band at your ankles","note":"Or sit lower as you step"}'),
('banded-squat','banded-squat','Banded squat','With a mini band above your knees, push your knees out and sit your hips down, then stand back up.','{"name":"Bodyweight squat","note":"No band","exercise_id":"bodyweight-squat"}','{"name":"Pause at the bottom","note":"Hold for 2 seconds each rep"}'),
('barbell-row','barbell-row','Barbell row','Hinge forward with a flat back, pull the bar to your lower ribs, then lower it with control.','{"name":"One-arm dumbbell row","note":"Support yourself on a bench","exercise_id":"single-arm-db-row"}','{"name":"Pause at your ribs","note":"1 second, or add 5 lb"}'),
('bear-crawl','bear-crawl','Bear crawl','On your hands and feet with knees just off the floor, crawl forward and back in small steps.','{"name":"Bear crawl hold","note":"Stay in place","exercise_id":"bear-plank-hold"}','{"name":"Slower steps","note":"Keep your hips level"}'),
('bench-dips','bench-dips','Chair dip','With your hands on the edge of a chair behind you, bend your elbows to lower your hips, then push back up.','{"name":"Feet closer","note":"Bend your knees more"}','{"name":"Straight legs","note":"Or feet up on a second chair"}'),
('bench-press','bench-press','Bench press','Lie on the bench, lower the bar to your mid chest with control, then press it straight back up.','{"name":"Dumbbell bench press","note":"Or use a lighter bar","exercise_id":"db-bench-press"}','{"name":"Pause on your chest","note":"1 second, or add 5 lb"}'),
('bent-over-db-row','bent-over-db-row','Dumbbell row','Lean forward with a flat back and pull the dumbbell up toward your hip, then lower it slowly.','{"name":"One-arm dumbbell row","note":"Support yourself on a bench","exercise_id":"single-arm-db-row"}','{"name":"Pause at the top","note":"Or go up 5 lb"}'),
('bicep-curl','bicep-curl','Bicep curl','Hold the dumbbells with palms facing forward, curl them up to your shoulders, then lower slowly.','{"name":"One arm at a time","note":"Or use lighter dumbbells"}','{"name":"Lower for 3 seconds","note":"Or go up 5 lb"}'),
('bird-dog','bird-dog','Bird dog','On your hands and knees, reach one arm forward and the opposite leg back, hold for a breath, then switch.','{"name":"Arms only","note":"Or legs only"}','{"name":"Bird dog hold","note":"3 seconds each rep","exercise_id":"bird-dog-hold"}'),
('bodyweight-calf-raise','bodyweight-calf-raise','Calf raise','Stand tall, rise up onto your toes, pause, then lower your heels slowly.','{"name":"Hold a wall","note":"For balance"}','{"name":"Single-leg calf raise","note":"One foot at a time","exercise_id":"single-leg-calf-raise"}'),
('bodyweight-reverse-lunge','bodyweight-reverse-lunge','Reverse lunge','Step one foot back and lower your back knee toward the floor, then push through your front foot to stand.','{"name":"Hold a wall","note":"Or don''t lower as far"}','{"name":"Bulgarian split squat","note":"Back foot on a couch or bench","exercise_id":"bulgarian-split-squat"}'),
('bodyweight-squat','bodyweight-squat','Bodyweight squat','Stand with feet shoulder-width apart, sit your hips back and down, then stand up.','{"name":"Sit-to-stand from a chair","note":"Tap a chair with your hips each rep","exercise_id":"box-squat"}','{"name":"Pause at the bottom","note":"Hold for 2 seconds each rep"}'),
('bulgarian-split-squat','bulgarian-split-squat','Bulgarian split squat','Rest your back foot on a bench, lower your back knee toward the floor, then push up through your front foot.','{"name":"Split squat","note":"Both feet on the floor","exercise_id":"split-squat"}','{"name":"Lower for 3 seconds","note":"Or hold heavier dumbbells"}'),
('butterfly-stretch','butterfly-stretch','Butterfly stretch','Sit with the soles of your feet together and let your knees fall out, then gently lean forward.','{"name":"Feet farther out","note":"Or sit on a cushion"}','{"name":"Feet closer in","note":"Lean a little further forward"}'),
('cable-curl','cable-curl','Cable curl','Hold the bar with palms up and elbows at your sides, curl it up to your shoulders, then lower slowly.','{"name":"Lighter pin","note":"Or curl one arm at a time"}','{"name":"Lower for 3 seconds","note":"Or move the pin one step heavier"}'),
('cable-kickback','cable-kickback','Cable kickback','With the strap around one ankle, hold the machine and push that leg back and up, squeezing your glutes, then return slowly.','{"name":"Glute kickback","note":"On the floor, no weight","exercise_id":"glute-kickback"}','{"name":"Pause at the top","note":"Hold for 2 seconds each rep"}'),
('cable-lateral-raise','cable-lateral-raise','Cable lateral raise','Stand side-on to the cable and lift the handle out to shoulder height with a soft elbow, then lower slowly.','{"name":"Lateral raise","note":"Light dumbbells instead","exercise_id":"lateral-raise"}','{"name":"Lower for 3 seconds","note":"Or move the pin one step heavier"}'),
('cable-pull-through','cable-pull-through','Cable pull-through','Face away from the cable holding the rope between your legs, push your hips back, then drive them forward to stand tall.','{"name":"Lighter pin","note":"Or a shorter hinge"}','{"name":"Pause at the top","note":"Squeeze your glutes for 2 seconds"}'),
('cat-cow','cat-cow','Cat-cow','On your hands and knees, round your back up toward the ceiling, then let your belly drop and lift your chest.','{"name":"Smaller range","note":"Move slowly"}','{"name":"Slower reps","note":"5 seconds each way"}'),
('chest-press-machine','chest-press-machine','Chest press machine','Sit tall with the handles at chest height, push them straight out, then let them come back slowly.','{"name":"Incline push-up","note":"Hands on a bench or bar","exercise_id":"incline-push-ups"}','{"name":"Dumbbell bench press","note":"Once the machine feels easy","exercise_id":"db-bench-press"}'),
('childs-pose','childs-pose','Child''s pose','Kneel and sit back on your heels, then fold forward and rest your arms and forehead on the floor.','{"name":"Knees wide","note":"Or a pillow under your chest"}','{"name":"Walk your hands to one side","note":"Then the other, to stretch your sides"}'),
('cobra-stretch','cobra-stretch','Cobra stretch','Lie face down with your hands under your shoulders and gently press your chest up, keeping your hips on the floor.','{"name":"Sphinx","note":"Stay on your forearms"}','{"name":"Straighter arms","note":"Only as far as feels good"}'),
('cossack-squat','cossack-squat','Cossack squat','Stand with your feet wide, shift your weight and sit down over one leg while the other stays straight, then switch.','{"name":"Side lunge","note":"Don''t go as low","exercise_id":"side-lunge"}','{"name":"Pause at the bottom","note":"Hold for 2 seconds each side"}'),
('cross-body-shoulder-stretch','cross-body-shoulder-stretch','Cross-body shoulder stretch','Bring one arm across your chest and hold it close with your other arm until you feel a stretch in your shoulder.','{"name":"Gentler pull","note":"Hold above the elbow"}','{"name":"Turn your head away","note":"From the arm being stretched"}'),
('db-bench-press','db-bench-press','Dumbbell bench press','Lie on a bench with a dumbbell in each hand at chest level, press them straight up, then lower them slowly.','{"name":"Machine chest press","note":"Or use lighter dumbbells","exercise_id":"chest-press-machine"}','{"name":"Lower for 4 seconds","note":"Or go up 5 lb"}'),
('db-goblet-squat','db-goblet-squat','Goblet squat','Hold one dumbbell at your chest, sit your hips down as low as feels comfortable, then stand back up.','{"name":"Bodyweight squat","note":"Or use a lighter dumbbell","exercise_id":"bodyweight-squat"}','{"name":"Pause at the bottom","note":"Or go up 5 lb"}'),
('dead-bug','dead-bug','Dead bug','Lie on your back with arms up and knees bent, then slowly lower the opposite arm and leg while keeping your lower back on the floor.','{"name":"Feet stay down","note":"Only lower your arms"}','{"name":"Slower reps","note":"Take 3 seconds to lower each side"}'),
('dead-bug-hold','dead-bug-hold','Dead bug hold','Lie on your back with arms up and knees bent, lower one arm and the opposite leg, then hold with your lower back on the floor.','{"name":"Dead bug","note":"Keep moving instead of holding","exercise_id":"dead-bug"}','{"name":"Longer hold","note":"Add 10 seconds"}'),
('deadlift','deadlift','Deadlift','Stand with the bar over your mid-foot, grip it with a flat back, push the floor away to stand tall, then lower it with control.','{"name":"Kettlebell deadlift","note":"Or lift the bar from blocks","exercise_id":"kettlebell-deadlift"}','{"name":"Pause just off the floor","note":"1 second, or add 10 lb"}'),
('decline-push-up','decline-push-up','Decline push-up','With your feet up on a chair or step, lower your chest toward the floor, then push back up.','{"name":"Push-up","note":"Feet on the floor","exercise_id":"push-up"}','{"name":"Higher feet","note":"Or lower for 3 seconds"}'),
('deep-squat-hold','deep-squat-hold','Deep squat hold','Sit down into your deepest comfortable squat with your heels down and chest up, then hold.','{"name":"Hold onto something","note":"A door frame or a sturdy chair"}','{"name":"Hands overhead","note":"Keep your chest tall"}'),
('doorway-chest-stretch','doorway-chest-stretch','Doorway chest stretch','Rest your forearms on a door frame at shoulder height and step forward until you feel a stretch across your chest.','{"name":"Smaller step","note":"Or one arm at a time"}','{"name":"Step further","note":"Or raise your arms a little higher"}'),
('dumbbell-hip-thrust','dumbbell-hip-thrust','Dumbbell hip thrust','Sit with your upper back against a bench and a dumbbell on your hips, push your hips up until your body is flat, then lower.','{"name":"Glute bridge","note":"On the floor, no weight","exercise_id":"glute-bridge"}','{"name":"Single-leg hip thrust","note":"Or go up 10 lb","exercise_id":"single-leg-hip-thrust"}'),
('dumbbell-romanian-deadlift','dumbbell-romanian-deadlift','Dumbbell Romanian deadlift','Hold the dumbbells in front of your thighs, push your hips back with a flat back until the backs of your legs stretch, then stand tall.','{"name":"Shorter range","note":"Stop at your knees, or use lighter dumbbells"}','{"name":"Lower for 3 seconds","note":"Or go up 5 lb"}'),
('dumbbell-shoulder-press','dumbbell-shoulder-press','Dumbbell shoulder press','Hold the dumbbells at your shoulders, push them straight overhead, then lower them back down.','{"name":"One arm at a time","note":"Or use lighter dumbbells","exercise_id":"one-arm-dumbbell-shoulder-press"}','{"name":"Lower for 3 seconds","note":"Or go up 5 lb"}'),
('face-pull','face-pull','Face pull','Pull the rope toward your face with your elbows high, spreading your hands apart, then let it back slowly.','{"name":"Rear-delt fly","note":"Light dumbbells instead","exercise_id":"rear-delt-fly"}','{"name":"Pause for 2 seconds","note":"Hands beside your ears"}'),
('glute-bridge','glute-bridge','Glute bridge','Lie on your back with knees bent, squeeze your glutes and lift your hips until your body is straight, then lower.','{"name":"Smaller lift","note":"Raise your hips only halfway"}','{"name":"Single-leg glute bridge","note":"One foot on the floor","exercise_id":"single-leg-glute-bridge"}'),
('glute-bridge-hold','glute-bridge-hold','Glute bridge hold','Lift your hips into a glute bridge and hold them up, squeezing your glutes the whole time.','{"name":"Shorter hold","note":"20 seconds"}','{"name":"Single-leg bridge hold","note":"Switch legs halfway","exercise_id":"single-leg-glute-bridge-hold"}'),
('glute-kickback','glute-kickback','Glute kickback','On your hands and knees with a band around your legs, push one leg back and up, squeezing your glutes.','{"name":"No band","note":"Same move, slower"}','{"name":"Pause at the top","note":"Hold for 2 seconds each rep"}'),
('goblet-squat','goblet-squat','Goblet squat','Hold the kettlebell at your chest, sit your hips down as low as feels comfortable, then stand back up.','{"name":"Bodyweight squat","note":"Same move, no bell","exercise_id":"bodyweight-squat"}','{"name":"Pause at the bottom","note":"Hold for 2 seconds each rep"}'),
('hammer-curl','hammer-curl','Hammer curl','Hold the dumbbells with palms facing each other, curl them up to your shoulders, then lower slowly.','{"name":"One arm at a time","note":"Or use lighter dumbbells"}','{"name":"Lower for 3 seconds","note":"Or go up 5 lb"}'),
('high-foot-leg-press','high-foot-leg-press','High-foot leg press','Sit in the leg press with your feet high on the platform, lower it toward your chest, then press it away through your heels.','{"name":"Lighter pin","note":"Or bend your knees a little less"}','{"name":"Lower for 3 seconds","note":"Or add 10 lb"}'),
('high-knees','high-knees','High knees','Run in place, driving each knee up toward hip height and pumping your arms.','{"name":"High-knee march","note":"March instead of running in place"}','{"name":"Faster pace","note":"Stay light on your feet"}'),
('hip-abduction','hip-abduction','Hip abduction machine','Sit in the machine with the pads outside your knees, push your knees apart, then let them come back slowly.','{"name":"Lighter pin","note":"Or a shorter range"}','{"name":"Lean forward","note":"Hinge a little to work your glutes more"}'),
('hip-thrust','hip-thrust','Barbell hip thrust','Sit with your upper back on a bench and a padded bar across your hips, push your hips up until your body is flat, then lower.','{"name":"Dumbbell hip thrust","note":"One dumbbell on your hips","exercise_id":"dumbbell-hip-thrust"}','{"name":"Pause at the top","note":"2 seconds, or add 10 lb"}'),
('hollow-body-hold','hollow-body-hold','Hollow body hold','Lie on your back, press your lower back into the floor and lift your shoulders and legs a little off the floor, then hold.','{"name":"Knees bent","note":"Arms by your sides"}','{"name":"Arms overhead","note":"And legs lower to the floor"}'),
('inchworm','inchworm','Inchworm','Bend down to put your hands on the floor, walk them out to a push-up position, then walk them back and stand up.','{"name":"Bend your knees","note":"As much as you need"}','{"name":"Add a push-up","note":"At the bottom of each rep","exercise_id":"push-up"}'),
('incline-db-press','incline-db-press','Incline dumbbell press','Lie on a bench propped up at an angle and press the dumbbells up from your upper chest, then lower slowly.','{"name":"Incline push-up","note":"Or use lighter dumbbells","exercise_id":"incline-push-ups"}','{"name":"Lower for 4 seconds","note":"Or go up 5 lb"}'),
('incline-treadmill-walk','incline-treadmill-walk','Incline treadmill walk','Walk on the treadmill with the incline raised, at a pace where you could still talk.','{"name":"Flat walk","note":"Lower the incline to zero"}','{"name":"Steeper hill","note":"Raise the incline one step"}'),
('jumping-jacks','jumping-jacks','Jumping jacks','Jump your feet out as your arms go overhead, then back in; step side to side instead for a gentler version.','{"name":"Step jack","note":"Step one foot out at a time"}','{"name":"Faster pace","note":"Stay light on your feet"}'),
('kettlebell-deadlift','kettlebell-deadlift','Kettlebell deadlift','Stand with the kettlebell between your feet, push your hips back with a flat back to grab it, then stand tall.','{"name":"Lighter bell","note":"Or raise it on a step"}','{"name":"Pause at the top","note":"Squeeze your glutes for 2 seconds"}'),
('kettlebell-halo','kettlebell-halo','Kettlebell halo','Hold the kettlebell upside down by the handle and circle it slowly around your head, keeping your ribs down.','{"name":"Smaller circles","note":"Or use a lighter weight"}','{"name":"Half-kneeling halo","note":"Kneel on one knee to work your core more"}'),
('kettlebell-reverse-lunge','kettlebell-reverse-lunge','Kettlebell reverse lunge','Hold the kettlebell at your chest, step one foot back and lower your back knee toward the floor, then push through your front foot to stand.','{"name":"Reverse lunge","note":"Same move, no bell","exercise_id":"bodyweight-reverse-lunge"}','{"name":"Lower for 3 seconds","note":"Or use a heavier bell"}'),
('kettlebell-swing','kettlebell-swing','Kettlebell swing','Hinge at your hips to swing the bell back between your legs, then snap your hips forward to float it up to chest height.','{"name":"Kettlebell deadlift","note":"Learn the hip hinge first","exercise_id":"kettlebell-deadlift"}','{"name":"One-arm swing","note":"Switch hands each round","exercise_id":"one-arm-kettlebell-swing"}'),
('knee-push-ups','knee-push-ups','Knee push-ups','With your knees on the floor and your body straight from head to knees, lower your chest toward the floor, then push back up.','{"name":"Incline push-up","note":"Hands on a bench or step","exercise_id":"incline-push-ups"}','{"name":"Push-up","note":"Off your knees for the first reps","exercise_id":"push-up"}'),
('knee-to-chest-stretch','knee-to-chest-stretch','Knee-to-chest stretch','Lie on your back and hug one knee toward your chest, keeping the other leg relaxed.','{"name":"Other knee bent","note":"Foot flat on the floor"}','{"name":"Both knees","note":"Hug both in together"}'),
('kneeling-hip-flexor-stretch','kneeling-hip-flexor-stretch','Kneeling hip flexor stretch','Kneel on one knee, tuck your hips under and shift forward until you feel a stretch at the front of your hip.','{"name":"Cushion under your knee","note":"Or hold a chair for balance"}','{"name":"Reach up","note":"Raise the arm on the kneeling side"}'),
('lat-pulldown','lat-pulldown','Lat pulldown','Sit under the bar, pull it down to your upper chest with your elbows pointing down, then let it rise slowly.','{"name":"Lighter pin","note":"Pause with the bar at your chest"}','{"name":"Assisted pull-up","note":"Use a little less help each week","exercise_id":"assisted-pull-ups"}'),
('lateral-raise','lateral-raise','Lateral raise','Hold light dumbbells at your sides and lift them out to shoulder height, then lower them slowly.','{"name":"Seated lateral raise","note":"Sitting stops the swing","exercise_id":"seated-dumbbell-lateral-raise"}','{"name":"Lower for 3 seconds","note":"Or use the next dumbbell up"}'),
('leg-curl','leg-curl','Leg curl','Lie face down with the pad just above your heels, curl your heels toward your glutes, then lower slowly.','{"name":"Seated leg curl","note":"Or move the pin one step lighter","exercise_id":"seated-leg-curl"}','{"name":"One leg at a time","note":"Lighter pin, same reps","exercise_id":"single-leg-lying-leg-curl"}'),
('leg-extension','leg-extension','Leg extension','Sit with the pad on your shins, straighten your legs until they are level, then lower slowly.','{"name":"Lighter pin","note":"Or stop just short of straight"}','{"name":"One leg at a time","note":"Lighter pin, same reps","exercise_id":"single-leg-extension"}'),
('leg-press','leg-press','Leg press','Sit in the machine with your feet on the platform, bend your knees toward your chest, then press the platform away.','{"name":"Sit-to-stand from a chair","note":"Or move the pin one step lighter","exercise_id":"box-squat"}','{"name":"Lower for 3 seconds","note":"Or move the pin one step heavier"}'),
('machine-shoulder-press','machine-shoulder-press','Machine shoulder press','Sit tall with the handles at shoulder height, press them overhead, then lower them slowly.','{"name":"Lighter pin","note":"Move it up a step and slow down"}','{"name":"Dumbbell shoulder press","note":"Once the machine feels easy","exercise_id":"dumbbell-shoulder-press"}'),
('mountain-climbers','mountain-climbers','Mountain climbers','From the top of a push-up, bring one knee toward your chest at a time at a steady pace.','{"name":"Hands on a bench","note":"Same move, slower pace"}','{"name":"Faster pace","note":"Keep your hips level"}'),
('ohp','ohp','Overhead press','Stand tall with the bar at your shoulders, press it straight overhead, then lower it back to your shoulders.','{"name":"Dumbbell shoulder press","note":"Lighter and easier to learn","exercise_id":"dumbbell-shoulder-press"}','{"name":"Pause overhead","note":"1 second, or add 5 lb"}'),
('one-arm-kettlebell-row','one-arm-kettlebell-row','One-arm kettlebell row','With one hand on a bench or your knee, pull the kettlebell up toward your hip, then lower it slowly.','{"name":"Chest-supported row","note":"Lie face down on an incline bench","exercise_id":"chest-supported-kettlebell-row"}','{"name":"Pause at the top","note":"Hold for 2 seconds each rep"}'),
('overhead-tricep-extension','overhead-tricep-extension','Overhead triceps extension','Hold one dumbbell overhead with both hands, bend your elbows to lower it behind your head, then straighten your arms.','{"name":"Triceps kickback","note":"Lighter, one arm at a time","exercise_id":"tricep-kickback"}','{"name":"Lower for 3 seconds","note":"Or go up 5 lb"}'),
('pigeon-stretch','pigeon-stretch','Pigeon stretch','From your hands and knees, bring one knee forward behind your wrist and slide the other leg back, then lower your hips.','{"name":"Pillow under your hip","note":"Or stay up on your hands"}','{"name":"Fold forward","note":"Lower your chest over your front leg"}'),
('pike-push-ups','pike-push-ups','Pike push-up','With your hips high in an upside-down V, bend your elbows to lower your head toward the floor, then push back up.','{"name":"Smaller range","note":"Lower your head only halfway"}','{"name":"Feet on a chair","note":"Puts more weight on your shoulders"}'),
('plank','plank','Plank','Hold your body in a straight line on your forearms and toes, keeping your belly tight.','{"name":"Incline plank","note":"Forearms on a bench or chair","exercise_id":"incline-plank-hold"}','{"name":"Longer hold","note":"Add 10 seconds"}'),
('push-up','push-up','Push-up','Lower your chest toward the floor with your body straight, then push back up.','{"name":"Incline push-up","note":"Hands on a bench or step","exercise_id":"incline-push-ups"}','{"name":"Lower for 3 seconds","note":"Pause just above the floor"}'),
('rear-delt-fly','rear-delt-fly','Rear-delt fly','Lean forward with a flat back and lift light dumbbells out to the sides, squeezing your shoulder blades together.','{"name":"Lighter dumbbells","note":"Or rest your chest on an incline bench"}','{"name":"Pause at the top","note":"Hold for 2 seconds each rep"}'),
('reverse-crunches','reverse-crunches','Reverse crunch','Lie on your back with knees bent up, curl your hips off the floor to bring your knees toward your chest, then lower slowly.','{"name":"Smaller lift","note":"Just tilt your hips"}','{"name":"Lower for 3 seconds","note":"With straighter legs"}'),
('reverse-lunge','reverse-lunge','Reverse lunge','Step one foot back and lower your back knee toward the floor, then push through your front foot to stand.','{"name":"Reverse lunge, no weights","note":"Hold a wall for balance","exercise_id":"bodyweight-reverse-lunge"}','{"name":"Bulgarian split squat","note":"Back foot on a bench","exercise_id":"bulgarian-split-squat"}'),
('romanian-deadlift','romanian-deadlift','Romanian deadlift','Hold the bar in front of your thighs, push your hips back with a flat back until the backs of your legs stretch, then stand tall.','{"name":"Dumbbell Romanian deadlift","note":"Lighter and easier to learn","exercise_id":"dumbbell-romanian-deadlift"}','{"name":"Lower for 3 seconds","note":"Or add 10 lb"}'),
('run:10k','running','Your 10K','Run your full 10K at an easy pace; it doesn''t matter how long it takes.','{"name":"Run / walk","note":"Walk 1 min every 10"}','{"name":"Even pace","note":"Same speed start to finish"}'),
('run:easy','running','Easy run','Run at a slow, easy pace where you could still talk; walk for a bit if you need to.','{"name":"Run / walk","note":"Walk 1 min whenever you need"}','{"name":"Finish with strides","note":"4 x 15 sec a little faster"}'),
('run:long','running','Long run','Run slowly the whole way at a pace where you could still talk; walk for a minute if you need to.','{"name":"Run / walk","note":"Walk 1 min every 10"}','{"name":"Same time, smoother","note":"Keep the pace even"}'),
('run:steady','running','Steady run','Start easy, then hold a pace where you can say a few words but not chat, then finish easy.','{"name":"Shorter steady part","note":"Cut it by 5 minutes"}','{"name":"Steady a bit faster","note":"Still able to say a few words"}'),
('run:warmup','walking','Brisk walk warm-up','Walk briskly for 5 minutes to warm up before you start running.','{"name":"Easy walk","note":"Any pace that warms you up"}','{"name":"Faster walk","note":"Swing your arms"}'),
('russian-twist','russian-twist','Russian twist','Sit leaning back with knees bent and feet down, then turn your chest and hands to one side, then the other.','{"name":"Lean back less","note":"Hands on your knees"}','{"name":"Feet up","note":"Or hold a weight"}'),
('seated-cable-row','seated-cable-row','Seated cable row','Sit tall holding the handle, pull it to your belly while squeezing your shoulder blades, then let your arms straighten slowly.','{"name":"Chest-supported row","note":"The pad holds your chest still","exercise_id":"chest-supported-machine-row"}','{"name":"Pause for 2 seconds","note":"Hold the handle at your belly"}'),
('seated-leg-curl','seated-leg-curl','Seated leg curl','Sit with the pad just above your heels, bend your knees to pull it down and under you, then let it rise slowly.','{"name":"Glute bridge","note":"Or move the pin one step lighter","exercise_id":"glute-bridge"}','{"name":"Lower for 3 seconds","note":"Or move the pin one step heavier"}'),
('shrimp-squat','shrimp-squat','Shrimp squat','Stand on one leg holding a wall, hold your other foot behind you and lower that knee toward the floor, then stand up.','{"name":"Split squat","note":"Back foot on the floor","exercise_id":"split-squat"}','{"name":"Hands-free","note":"Let go of the wall"}'),
('side-lunge','side-lunge','Side lunge','Step wide to one side and sit your hips back over that foot with the other leg straight, then push back to the middle.','{"name":"Shorter step","note":"Go only as low as feels comfortable"}','{"name":"Cossack squat","note":"Sink lower each rep","exercise_id":"cossack-squat"}'),
('side-lying-hip-abduction','side-lying-hip-abduction','Side-lying leg raise','Lie on your side with your legs straight, lift your top leg toward the ceiling, then lower it slowly.','{"name":"Bend your bottom knee","note":"For a steadier base"}','{"name":"Add the band","note":"Mini band above your knees"}'),
('side-plank','side-plank','Side plank','Lie on your side and lift your hips so your body is straight from head to feet, resting on your forearm.','{"name":"Knees down","note":"Bottom knee on the floor"}','{"name":"Lift your top leg","note":"Or add 10 seconds","exercise_id":"side-plank-leg-lift"}'),
('single-arm-db-row','single-arm-db-row','One-arm dumbbell row','With one hand and knee on a bench, pull the dumbbell up toward your hip, then lower it slowly.','{"name":"Chest-supported row","note":"Lie face down on an incline bench","exercise_id":"chest-supported-db-row"}','{"name":"Pause at the top","note":"Or go up 5 lb"}'),
('single-leg-calf-raise','single-leg-calf-raise','Single-leg calf raise','Stand on one foot holding a wall for balance, rise up onto your toes, then lower your heel slowly.','{"name":"Calf raise","note":"Both feet","exercise_id":"bodyweight-calf-raise"}','{"name":"Off a step","note":"Let your heel drop below the step"}'),
('single-leg-glute-bridge','single-leg-glute-bridge','Single-leg glute bridge','Lie on your back with one foot on the floor and the other leg lifted, push your hips up, then lower.','{"name":"Glute bridge","note":"Both feet down","exercise_id":"glute-bridge"}','{"name":"Single-leg hip thrust","note":"Upper back on a couch or bench","exercise_id":"single-leg-hip-thrust"}'),
('split-squat','split-squat','Split squat','Stand with one foot forward and one back, lower your back knee toward the floor, then push back up without moving your feet.','{"name":"Hold a wall","note":"Or don''t lower as far"}','{"name":"Bulgarian split squat","note":"Back foot on a couch or chair","exercise_id":"bulgarian-split-squat"}'),
('squat','squat','Squat','With the bar across your upper back, sit your hips down until your thighs are about level, then stand back up.','{"name":"Goblet squat","note":"One dumbbell at your chest","exercise_id":"db-goblet-squat"}','{"name":"Pause at the bottom","note":"1 second, or add 10 lb"}'),
('standing-calf-raise','standing-calf-raise','Standing calf raise','Stand tall under the pads, rise up onto your toes, pause, then lower your heels slowly.','{"name":"Calf raise","note":"Bodyweight, on the floor","exercise_id":"bodyweight-calf-raise"}','{"name":"Pause at the top","note":"Hold for 2 seconds each rep"}'),
('standing-quad-stretch','standing-quad-stretch','Standing quad stretch','Stand on one leg holding a wall and pull your other heel toward your glutes until the front of your thigh stretches.','{"name":"Lying on your side","note":"No balance needed"}','{"name":"Hands-free","note":"Let go of the wall"}'),
('suitcase-carry','suitcase-carry','Suitcase carry','Hold the kettlebell in one hand at your side, stand tall without leaning and walk steadily until the time is up.','{"name":"Shorter walk","note":"20 sec each side"}','{"name":"Heavier bell","note":"Or walk slower and taller"}'),
('superman','superman','Superman','Lie face down and lift your arms, chest and legs a little off the floor, then lower them.','{"name":"Arms only","note":"Keep your legs on the floor"}','{"name":"Hold at the top","note":"3 seconds each rep"}'),
('tricep-pushdown','tricep-pushdown','Triceps pushdown','Hold the bar or rope with your elbows tucked at your sides, push it down until your arms are straight, then let it rise slowly.','{"name":"Lighter pin","note":"Keep your elbows pinned to your sides"}','{"name":"Overhead cable extension","note":"Face away from the cable","exercise_id":"cable-overhead-tricep-extension"}'),
('wall-hamstring-stretch','wall-hamstring-stretch','Wall hamstring stretch','Lie on your back in a doorway with one leg up the wall and the other flat on the floor, then relax into the stretch.','{"name":"Scoot back","note":"Move your hips away from the wall"}','{"name":"Scoot closer","note":"Bring your hips nearer the wall"}'),
('worlds-greatest-stretch','worlds-greatest-stretch','World''s greatest stretch','Step into a long lunge, put both hands on the floor inside your front foot, then twist and reach that arm to the ceiling.','{"name":"Back knee down","note":"Rest it on the floor"}','{"name":"Hold each reach","note":"3 seconds at the top"}');
INSERT INTO public.plans (slug, name, goal, level, weeks, days_per_week, minutes, gear, gear_short, equipment_key, summary, focus_line, progression_rule, safety_note, note, sort_order, is_published, cover_url, cover_credit, week_notes) VALUES
('gym-first-steps', 'Gym First Steps', 'beginner', 'Total beginner', 4, 3, '40', ARRAY['Gym membership']::text[], 'Gym', 'gym', 'Your first month in a gym, on machines that guide the movement for you.', 'Full body on machines, plus an easy incline walk', '2 sets in weeks 1-2, 3 sets in weeks 3-4. Hit the top of the range on every set? Move the pin one step heavier next time.', 'New to exercise, pregnant, or managing an injury or health condition? Check with a doctor before starting. Stop if anything hurts.', NULL, 3, true, 'https://images.unsplash.com/photo-1790094180990-02826069d59b?w=1200&q=70&fit=crop&auto=format', 'Stefan Vibes', '[{"week":1,"emoji":"🌱","title":"Learn the machines","note":"2 sets each. Pick a pin where the last reps feel hard but clean.","lighter":false},{"week":2,"emoji":"➕","title":"One more rep","note":"Still 2 sets. Add a rep where you can.","lighter":false},{"week":3,"emoji":"📈","title":"Add a third set","note":"3 sets of everything, same pins as week 2.","lighter":false},{"week":4,"emoji":"🏆","title":"Then vs now","note":"3 sets, one pin heavier where you hit the top of the range.","lighter":false}]'::jsonb),
('twenty-minute-burn', '20-Minute Burn', 'fat_loss', 'Beginner', 4, 3, '20', '{}'::text[], 'No equipment', 'none', 'Three quick circuits a week that get your heart rate up, no gear needed.', 'Full body circuits that get your heart pumping', 'Add a round in week 2 (5 rounds). Weeks 3-4: 40 sec on / 20 sec off.', 'New to exercise, pregnant, or managing an injury or health condition? Check with a doctor before starting. Stop if anything hurts.', NULL, 5, true, 'https://images.unsplash.com/photo-1518644961665-ed172691aaa1?w=1200&q=70&fit=crop&auto=format', 'bruce mars', '[{"week":1,"emoji":"🌱","title":"Find your pace","note":"4 rounds, 30 sec on / 30 sec off.","lighter":false},{"week":2,"emoji":"➕","title":"One more round","note":"5 rounds, same timing.","lighter":false},{"week":3,"emoji":"🔥","title":"Work longer","note":"5 rounds, 40 sec on / 20 sec off.","lighter":false},{"week":4,"emoji":"🏆","title":"Finish strong","note":"Same as week 3. Notice how much easier it feels.","lighter":false}]'::jsonb),
('kettlebell-burn', 'Kettlebell Burn', 'fat_loss', 'Beginner', 6, 3, '30', ARRAY['One kettlebell']::text[], 'One kettlebell', 'kettlebell', 'Swings, squats and carries with one kettlebell for a full-body sweat in 30 minutes.', 'Full body, mostly glutes, legs and grip', 'Add 5 swings per round every 2 weeks. Week 4 is lighter: 3 rounds.', 'New to exercise, pregnant, or managing an injury or health condition? Check with a doctor before starting. Stop if anything hurts.', NULL, 6, true, 'https://images.unsplash.com/photo-1706029831387-fd8bc3d27d01?w=1200&q=70&fit=crop&auto=format', 'Ambitious Studio / Rick Barrett', '[{"week":1,"emoji":"🌱","title":"Learn the swing","note":"15 swings a round. Pick a bell you can swing with a flat back.","lighter":false},{"week":2,"emoji":"➕","title":"Smoother swings","note":"Same rounds. Make every swing crisp.","lighter":false},{"week":3,"emoji":"📈","title":"More swings","note":"20 swings a round.","lighter":false},{"week":4,"emoji":"🌙","title":"Lighter week","note":"3 rounds of everything so your body catches up.","lighter":true},{"week":5,"emoji":"💪","title":"Back to work","note":"Full rounds again, 25 swings a round.","lighter":false},{"week":6,"emoji":"🏆","title":"Finish strong","note":"25 swings a round. Compare to week 1.","lighter":false}]'::jsonb),
('muscle-3-days', 'Muscle in 3 Days', 'muscle', 'Beginner', 8, 3, '45', ARRAY['Pair of dumbbells','Bench or sturdy step']::text[], 'Dumbbells + bench', 'dumbbells', 'Three full-body dumbbell workouts a week for people who can''t train every day.', 'Full body, every muscle three times a week', 'Start at the bottom of the rep range. Hit the top on every set? Go up 5 lb next time. Week 4 is lighter: 2 sets of everything.', 'New to exercise, pregnant, or managing an injury or health condition? Check with a doctor before starting. Stop if anything hurts.', NULL, 8, true, 'https://images.unsplash.com/photo-1641337221253-fdc7237f6b61?w=1200&q=70&fit=crop&auto=format', 'Luke Witter', '[{"week":1,"emoji":"🌱","title":"Learn the moves","note":"Light weights. Get the form right before adding weight.","lighter":false},{"week":2,"emoji":"➕","title":"One more rep","note":"Same weights, one more rep where you can.","lighter":false},{"week":3,"emoji":"📈","title":"First weight jump","note":"Hit the top of the range on every set? Add 5 lb.","lighter":false},{"week":4,"emoji":"🌙","title":"Lighter week","note":"2 sets of everything so your body catches up.","lighter":true},{"week":5,"emoji":"💪","title":"Back to work","note":"3 sets again, a little heavier than week 3.","lighter":false},{"week":6,"emoji":"📈","title":"Keep climbing","note":"Add reps, then weight.","lighter":false},{"week":7,"emoji":"🔥","title":"Your heaviest week","note":"Most people notice real changes by now.","lighter":false},{"week":8,"emoji":"🏆","title":"Then vs now","note":"Repeat Day 1 and compare it to week 1.","lighter":false}]'::jsonb),
('gym-upper-lower', 'Gym Upper / Lower', 'muscle', 'Intermediate', 8, 4, '50', ARRAY['Gym membership']::text[], 'Gym', 'gym', 'The classic gym split: two upper-body and two lower-body days a week.', 'Upper body twice and lower body twice a week', 'Top reps on every set? Add 5 lb, or 10 lb on squat and deadlift. Weeks 4 and 8 are lighter: one set fewer on everything.', 'New to exercise, pregnant, or managing an injury or health condition? Check with a doctor before starting. Stop if anything hurts.', NULL, 9, true, 'https://images.unsplash.com/photo-1609899537878-88d5ba429bdb?w=1200&q=70&fit=crop&auto=format', 'Matthew Sichkaruk', '[{"week":1,"emoji":"🌱","title":"Learn the split","note":"Start at the bottom of each rep range with weights you control.","lighter":false},{"week":2,"emoji":"➕","title":"One more rep","note":"Same weights, one more rep where you can.","lighter":false},{"week":3,"emoji":"📈","title":"First weight jump","note":"Top reps on every set? Add 5 lb, or 10 lb on squat and deadlift.","lighter":false},{"week":4,"emoji":"🌙","title":"Lighter week","note":"One set fewer on everything so your body catches up.","lighter":true},{"week":5,"emoji":"💪","title":"Back to work","note":"Full sets again, a little heavier than week 3.","lighter":false},{"week":6,"emoji":"📈","title":"Keep climbing","note":"Add reps, then weight.","lighter":false},{"week":7,"emoji":"🔥","title":"Your heaviest week","note":"Go for the top of every range.","lighter":false},{"week":8,"emoji":"🌙","title":"Lighter week","note":"One set fewer on everything. Compare your lifts to week 1.","lighter":true}]'::jsonb),
('glutes-at-home', 'Glutes at Home', 'glutes', 'Beginner', 6, 3, '25', ARRAY['Mini band']::text[], 'Mini band', 'band', 'Three band workouts a week for stronger glutes without leaving the house.', 'Glutes first, with legs in support', 'Add 2 reps a week. Reps feel easy at the top? Move to a stronger band and drop back down.', 'New to exercise, pregnant, or managing an injury or health condition? Check with a doctor before starting. Stop if anything hurts.', NULL, 11, true, 'https://images.unsplash.com/photo-1552226351-1ac7863af926?w=1200&q=70&fit=crop&auto=format', 'Gabriel Alenius', '[{"week":1,"emoji":"🌱","title":"Learn the moves","note":"The reps listed, with a band you can control.","lighter":false},{"week":2,"emoji":"➕","title":"Two more reps","note":"Add 2 reps to every set.","lighter":false},{"week":3,"emoji":"➕","title":"Keep adding reps","note":"2 more again where you can.","lighter":false},{"week":4,"emoji":"📈","title":"Stronger band","note":"Reps feel easy? Switch to a stronger band and drop back to the listed reps.","lighter":false},{"week":5,"emoji":"💪","title":"Build back up","note":"Add 2 reps a set with the new band.","lighter":false},{"week":6,"emoji":"🏆","title":"Your strongest week","note":"Go for your most reps yet.","lighter":false}]'::jsonb),
('gym-glutes', 'Gym Glutes', 'glutes', 'Intermediate', 8, 4, '45', ARRAY['Gym membership']::text[], 'Gym', 'gym', 'Barbell hip thrusts plus the gym machines that work glutes best.', 'Glutes first, with upper body in support', 'Add 2 reps a week until the top of the range, then add 10 lb and drop back to the bottom. Week 4 is lighter.', 'New to exercise, pregnant, or managing an injury or health condition? Check with a doctor before starting. Stop if anything hurts.', NULL, 12, true, 'https://images.unsplash.com/photo-1784819482930-07768d5db6f6?w=1200&q=70&fit=crop&auto=format', 'Galina Bogdanova', '[{"week":1,"emoji":"🌱","title":"Learn the moves","note":"Start at the bottom of each rep range.","lighter":false},{"week":2,"emoji":"➕","title":"Two more reps","note":"Same weights, 2 more reps per set.","lighter":false},{"week":3,"emoji":"📈","title":"First weight jump","note":"At the top of the range? Add 10 lb and start low again.","lighter":false},{"week":4,"emoji":"🌙","title":"Lighter week","note":"2 sets of everything so your body catches up.","lighter":true},{"week":5,"emoji":"💪","title":"Back to work","note":"Full sets again. Add 2 reps a set.","lighter":false},{"week":6,"emoji":"➕","title":"Keep adding reps","note":"2 more again where you can.","lighter":false},{"week":7,"emoji":"📈","title":"Next weight jump","note":"At the top of the range? Add 10 lb and drop back.","lighter":false},{"week":8,"emoji":"🏆","title":"Your strongest week","note":"Go for the top of every range.","lighter":false}]'::jsonb),
('strength-foundations', 'Strength Foundations', 'strength', 'Beginner–intermediate', 8, 3, '50', ARRAY['Barbell','Squat rack','Bench']::text[], 'Barbell + rack', 'gym', 'Learn the big five barbell lifts and add a little weight every week.', 'The big lifts: squat, bench, deadlift, press and row', 'Add 5 lb every workout to squat, bench, press and row, and 10 lb to deadlift. Miss your reps twice in a row? Drop 10% and build back.', 'New to exercise, pregnant, or managing an injury or health condition? Check with a doctor before starting. Stop if anything hurts.', NULL, 13, true, 'https://images.unsplash.com/photo-1770664612843-b44e26070024?w=1200&q=70&fit=crop&auto=format', 'Alef Morais', '[{"week":1,"emoji":"🌱","title":"Learn the lifts","note":"Start light, even just the bar. Clean reps first.","lighter":false},{"week":2,"emoji":"📈","title":"Add a little","note":"5 lb more each workout, 10 lb on deadlift.","lighter":false},{"week":3,"emoji":"📈","title":"Keep adding","note":"Same small jumps. Rest 2 to 3 min between sets.","lighter":false},{"week":4,"emoji":"💪","title":"Stay steady","note":"Missed your reps twice? Drop 10% and build back.","lighter":false},{"week":5,"emoji":"🔥","title":"Getting heavy","note":"Small jumps still. Brace hard before every rep.","lighter":false},{"week":6,"emoji":"📈","title":"Keep climbing","note":"Add weight while every rep stays clean.","lighter":false},{"week":7,"emoji":"🔥","title":"Your heaviest week","note":"Go for your heaviest sets of 5 yet.","lighter":false},{"week":8,"emoji":"🏆","title":"Then vs now","note":"Compare your lifts to week 1.","lighter":false}]'::jsonb),
('bodyweight-strength', 'Bodyweight Strength', 'strength', 'Intermediate', 8, 3, '30', '{}'::text[], 'No equipment', 'none', 'Make bodyweight moves harder every two weeks until push-ups and squats feel easy.', 'Full body strength with just your bodyweight', 'Every 2 weeks, move one step harder on each move, using its harder option.', 'New to exercise, pregnant, or managing an injury or health condition? Check with a doctor before starting. Stop if anything hurts.', NULL, 14, true, 'https://images.unsplash.com/photo-1598971457999-ca4ef48a9a71?w=1200&q=70&fit=crop&auto=format', 'Gordon Cowie', '[{"week":1,"emoji":"🌱","title":"Learn the moves","note":"Use the versions listed. Clean reps first.","lighter":false},{"week":2,"emoji":"➕","title":"Own it","note":"Same moves, smoother and steadier.","lighter":false},{"week":3,"emoji":"📈","title":"One step harder","note":"Switch to the harder option on each move.","lighter":false},{"week":4,"emoji":"💪","title":"Settle in","note":"Same versions as week 3, cleaner reps.","lighter":false},{"week":5,"emoji":"📈","title":"Another step up","note":"Move one step harder again.","lighter":false},{"week":6,"emoji":"💪","title":"Own it again","note":"Same versions as week 5, steadier reps.","lighter":false},{"week":7,"emoji":"🔥","title":"Hardest versions","note":"One more step harder where you can.","lighter":false},{"week":8,"emoji":"🏆","title":"Then vs now","note":"Try a week 1 move. Notice how easy it feels.","lighter":false}]'::jsonb),
('five-to-ten-k', '5K to 10K', 'run', 'Beginner–intermediate', 8, 4, '30–60', ARRAY['Running shoes']::text[], 'Running shoes', 'shoes', 'Already run a 5K? Build up to 10K with one longer run each week.', 'Legs and lungs, plus strength to stay injury-free', 'One run gets longer each week. Week 4 is lighter. Steady pace means you can say a few words but not chat.', 'New to exercise, pregnant, or managing an injury or health condition? Check with a doctor before starting. Stop if anything hurts.', 'Repeating a week is fine.', 16, true, 'https://images.unsplash.com/photo-1581889470536-467bdbe30cd0?w=1200&q=70&fit=crop&auto=format', 'Isaac Wendland', '[{"week":1,"emoji":"🌱","title":"Settle in","note":"Easy 25 min, steady 10 min, long run 35 min.","lighter":false},{"week":2,"emoji":"➕","title":"A bit longer","note":"Easy 25 min, steady 10 min, long run 40 min.","lighter":false},{"week":3,"emoji":"📈","title":"First 45","note":"Easy 30 min, steady 15 min, long run 45 min.","lighter":false},{"week":4,"emoji":"🌙","title":"Lighter week","note":"Easy 25 min, steady 10 min, long run 35 min.","lighter":true},{"week":5,"emoji":"💪","title":"Back to work","note":"Easy 30 min, steady 15 min, long run 50 min.","lighter":false},{"week":6,"emoji":"📈","title":"Steady 20","note":"Easy 30 min, steady 20 min, long run 55 min.","lighter":false},{"week":7,"emoji":"🔥","title":"Your longest run","note":"Easy 35 min, steady 20 min, long run 60 min.","lighter":false},{"week":8,"emoji":"🏆","title":"Your 10K","note":"Easy 25 min, steady 10 min. The long run is your 10K.","lighter":false}]'::jsonb),
('daily-mobility', 'Daily Mobility', 'mobility', 'All levels', 4, 5, '15', '{}'::text[], 'No equipment', 'none', 'Fifteen minutes of stretching to loosen tight hips, hamstrings and back.', 'Hips, hamstrings, back and shoulders', 'Hold each stretch a little longer each week. Never push into pain.', 'New to exercise, pregnant, or managing an injury or health condition? Check with a doctor before starting. Stop if anything hurts.', NULL, 17, true, 'https://images.unsplash.com/photo-1599901860904-17e6ed7083a0?w=1200&q=70&fit=crop&auto=format', 'Ginny Rose Stewart', '[{"week":1,"emoji":"🌱","title":"Find your range","note":"Hold each stretch as listed and breathe slowly.","lighter":false},{"week":2,"emoji":"➕","title":"A little longer","note":"Add 5 to 10 sec to each hold.","lighter":false},{"week":3,"emoji":"📈","title":"Ease in deeper","note":"Longer holds again. Ease in, never force it.","lighter":false},{"week":4,"emoji":"🏆","title":"Then vs now","note":"Notice what feels looser than in week 1.","lighter":false}]'::jsonb),
('core-strong', 'Core Strong', 'mobility', 'Beginner', 4, 3, '15', '{}'::text[], 'No equipment', 'none', 'Short core workouts that build a stronger middle and a steadier back.', 'Core and lower back', 'Add 5 sec to every hold and 2 reps to every set each week.', 'New to exercise, pregnant, or managing an injury or health condition? Check with a doctor before starting. Stop if anything hurts.', NULL, 18, true, 'https://images.unsplash.com/photo-1514512364185-4c2b0985be01?w=1200&q=70&fit=crop&auto=format', 'Ayo Ogunseinde', '[{"week":1,"emoji":"🌱","title":"Learn the moves","note":"Slow, controlled reps with your lower back down.","lighter":false},{"week":2,"emoji":"➕","title":"A little more","note":"Add 5 sec to every hold and 2 reps to every set.","lighter":false},{"week":3,"emoji":"📈","title":"Keep building","note":"5 sec and 2 reps more again.","lighter":false},{"week":4,"emoji":"🏆","title":"Your strongest week","note":"Compare to week 1. Notice how steady you feel.","lighter":false}]'::jsonb);
